type handler func(Message) error
var routes = map[string]handler{}

func register(kind string, h handler) { routes[kind] = h }   // build before serving

func route(m Message) error {
	if h, ok := routes[m.Kind]; ok {
		return h(m)              // a new kind needs no edit to the dispatcher
	}
	return handleUnroutable(m)   // lookup miss is the explicit fallback
}
